// Native API doubles: these checks test generated logic, not Redemption itself.
import java.util.*;
class CE {
 static class Thing {String template; float[] pos=new float[]{0,0,0},orientation=new float[]{0,0,0}; float health=100,maxHealth=100; int team=12; int location=0; int next=0,facing=0,motion=-1,baseMotion=-1; boolean item=false; List<Integer> inventory=new ArrayList<Integer>();}
 static Map<Integer,Thing> world=new HashMap<Integer,Thing>(); static boolean[] flags=new boolean[1024]; static int next=100,created=0,xp=0,location=0,released=0,questLoads=0,cameraTarget=0,conversationCalls=0,teleports=0;static boolean client=false,failSpawn=false,syncFeedback=false,syncEnd=false,failConversation=false,cutscene=false,aiOff=false; static String conversation="",music="",jump="";
 static Map<String,Integer> quests=new HashMap<String,Integer>();static Set<Integer> complete=new HashSet<Integer>();static List<Integer> save=new ArrayList<Integer>();static int read=0;
 static int make(String t,float[] p){if(failSpawn)return 0;Thing x=new Thing();x.template=t;x.pos=p.clone();x.location=location;x.item=t.contains("book")||t.contains("reward");world.put(next,x);created++;return next++;}
 static boolean valid(int g){return world.containsKey(g);}
}
class Codex {
 boolean CaptureThing(int g){return CE.valid(g);} boolean ReleaseThing(int g){return true;}
 boolean ExecuteText(int owner,int thing,String name){return true;}
 static boolean PreloadTemplate(String name){return !CE.failSpawn;}
 static final int CAM_SHOT_OTS_C=5,CAM_ANGLE_MEDIUM=2,CAM_DIST_CLOSEUP=1,MOTION_STAND=33,MOTION_IDLE=49,WORLD_CURRENT=12345678,THING_FLAG_SAVENEVER=1,THING_FLAG_SAVESUSPEND=2,THING_FLAG_SAVEALWAYS=8,THING_AF_AIPAUSED=4,THING_AF_NEUTRAL=8,THING_AF_TALKTO=16,TEAM_PEDESTRIANS=10,TEAM_ENEMY0=12,CONV_XFLAG_WANTFEEDBACK=4,CONV_XFLAG_ALLOWABORT=8,CAMERA_ANGLE_MEDIUM=1,CAMERA_ANGLE_LOW=0,CAMERA_ANGLE_HIGH=2,CAMERA_SHOT_MS=3,CAMERA_SHOT_CU=2,CAMERA_SHOT_WS=4;
 static boolean NetIsClient(){return CE.client;}static boolean IsPlayerGuid(int g){return g==1&&CE.valid(g);}static boolean IsActorGuid(int g){return CE.valid(g)&&!CE.world.get(g).item;}static boolean IsItemGuid(int g){return CE.valid(g)&&CE.world.get(g).item;}static boolean IsPropGuid(int g){return false;}static boolean IsWeaponGuid(int g){return false;}static boolean IsArmorGuid(int g){return false;}
 boolean CaptureThing(int g,int i){return CE.valid(g);}boolean SetTimer(float s,int id){return true;}boolean KillTimer(int id){return true;}void BeginCutscene(int p,int x){CE.cutscene=true;}void EndCutscene(int p,int x){CE.cutscene=false;}void AIOff(){CE.aiOff=true;}void AIOn(){CE.aiOff=false;}boolean ExecuteConversation(int p,int c,String name,String file,int f){CE.conversationCalls++;CE.conversation=name;if(CE.failConversation)return false;try { if(CE.syncFeedback)getClass().getMethod("convreached",int.class,int.class,int.class,int.class,int.class).invoke(this,p,0,0,0,0);if(CE.syncEnd)getClass().getMethod("convended",int.class,boolean.class,int.class).invoke(this,p,false,2); } catch(Exception e){throw new RuntimeException(e);}return true;}
}
class CodexThing extends Codex {
 boolean LookAtThing(int target){CE.world.get(guid).facing=target;return CE.valid(target);}
 int guid;CodexThing(int g){guid=g;}int GetLocationNum(){return CE.world.get(guid).location;}float[] GetPosition(){return CE.world.get(guid).pos.clone();}float[] GetOrientation(){return CE.world.get(guid).orientation.clone();}String GetTemplateName(){return CE.world.get(guid).template;}
 String GetDescriptionID(){return CE.world.get(guid).template;}
 int NextInWorld(){int next=0;for(Integer g:CE.world.keySet())if(g>guid&&(next==0||g<next))next=g;return next;}
 boolean Stop(){return true;}
 int PlayMotionSetMode(int mode,boolean base,float speed){if(base)CE.world.get(guid).baseMotion=mode;else CE.world.get(guid).motion=mode;return 2300;}
 static int GuidFromCastID(String id){for(Integer g:CE.world.keySet())if(CE.world.get(g).template.equals(id))return g;return 0;}
 boolean SetOrientation(float[] a){CE.world.get(guid).orientation=a.clone();return true;} int SpawnThingNear(String id,float d,int f){return CE.make(id,GetPosition());}int ClearThingFlags(int f){return f;}int SetThingFlags(int f){return f;}boolean Remove(){CE.world.remove(guid);return true;}
}
class CodexActor extends CodexThing {float GetActorMaxHealth(){return CE.world.get(guid).maxHealth;} float SetActorMaxHealth(float h){return CE.world.get(guid).maxHealth=h;} float SetActorHealth(float h){return CE.world.get(guid).health=h;} int GetActorTeam(){return CE.world.get(guid).team;} void StopActorAction(){} boolean CancelActorAction(){return true;} int PlayActorMotionSetMode(int m,boolean loop,float blend){return m;} CodexActor(int g){super(g);}int SetActorTeam(int t){return CE.world.get(guid).team=t;}int SetActorFlags(int f){return f;}int ClearActorFlags(int f){return f;}float GetActorHealth(){return CE.world.get(guid).health;}int GetActorFirstInventoryItem(){List<Integer> list=CE.world.get(guid).inventory;return list.size()==0?0:list.get(0);}boolean AddToActorInventory(int item){List<Integer> list=CE.world.get(guid).inventory;if(list.size()>0)CE.world.get(list.get(list.size()-1)).next=item;list.add(item);return true;}}
class CodexItem extends CodexThing {CodexItem(int g){super(g);}int GetNextInventoryItem(){return CE.world.get(guid).next;}int RemoveItemFromInventory(){for(CE.Thing t:CE.world.values())t.inventory.remove(Integer.valueOf(guid));return 1;}}
class CodexPlayer extends CodexActor {static boolean TeleportPartyToEntrance(int who,int entry){CE.teleports++;return CE.valid(who);}CodexPlayer(int g){super(g);}static int GetCurrentPlayer(){return CE.valid(1)?1:0;}static int GetNumMPPlayers(){return 1;}static int GetMPPlayer(int i){return GetCurrentPlayer();}boolean AwardPlayerExperience(int n){CE.xp+=n;return true;}}
class CodexWorld extends Codex {int GetFirstThing(){int first=0;for(Integer g:CE.world.keySet())if(first==0||g<first)first=g;return first;}CodexWorld(int g){}int CreateThing(String name,float[] p,float[] o){return CE.make(name,p);}}
class CodexSequence extends Codex {static int GetCurrentLocation(){return CE.location;}static boolean GetChronicleFlag(int f){return CE.flags[f];}static boolean SetChronicleFlag(int f){return CE.flags[f]=true;}static boolean ClearChronicleFlag(int f){return CE.flags[f]=false;}static void Jump(String s,int e){CE.jump=s;}static boolean SaveInt(int i){CE.save.add(i);return true;}static int RestoreInt(){return CE.save.get(CE.read++);}static boolean SaveFloat(float v){return SaveInt(Float.floatToIntBits(v));}static float RestoreFloat(){return Float.intBitsToFloat(RestoreInt());}static boolean SaveBoolean(boolean b){return SaveInt(b?1:0);}static boolean RestoreBoolean(){return RestoreInt()!=0;}}
class CodexQuest extends Codex {int id;CodexQuest(int g){id=g;}static int Load(String name){CE.questLoads++;if(!CE.quests.containsKey(name))CE.quests.put(name,CE.quests.size());return CE.quests.get(name);}void Complete(){CE.complete.add(id);}}
class CodexCamera extends Codex {static void SetupCutscene(int a,int b,int c){CE.cameraTarget=b;}static void Release(int g){CE.released++;CE.cameraTarget=0;}static void SetShot(int p,int s,int a,int d,int f,float t){}static void ShotAngle(int i){}static void ShotType(int i){}}
class CodexSound extends Codex {static boolean StartMusic(String name,int v){CE.music=name;return true;}static void StopMusic(){CE.music="";}static boolean StartAmbient(String n,int v){return true;}static void StopAmbient(){}}
class CodexConsole extends Codex {static void Print(int a,int b,String s){} static void PrintError(String s){} }
